#!/usr/bin/env python3
"""Build source-checked route specifications; never execute a campaign event."""
import json
from pathlib import Path

from inspect_campaign import REPO, load_npcs, load_stages, parse_tsc, resolve_original_path


DATA = REPO / "runtime/data"
STAGES = {stage.map.lower(): stage for stage in load_stages(DATA, REPO / "runtime/Doukutsu.exe")}
STEPS = []


def step(name, map_name, event, action="interact", **details):
    stage = STAGES[map_name.lower()]
    path = resolve_original_path(DATA / "Stage" / f"{stage.map}.tsc")
    page = parse_tsc(path.read_bytes())
    if event not in page:
        raise ValueError(f"Undefined route observation {map_name}#{event:04}")
    for field in ("result_event", "following_event", "native_death_event", "observed_transfer_event"):
        if field in details and details[field] not in page:
            raise ValueError(f"Undefined route {field} {map_name}#{details[field]:04}")
    for observation in details.get("observed_events", []):
        if observation not in page:
            raise ValueError(f"Undefined route observation {map_name}#{observation:04}")
    npcs = load_npcs(resolve_original_path(DATA / "Stage" / f"{stage.map}.pxe"))
    targets = [{"type": npc["type"], "x": npc["x"] * 16, "y": npc["y"] * 16, "appearance_flag": npc["flag"], "flags": npc["flags"]} for npc in npcs if npc["event"] == event]
    row = {"name": name, "stage": stage.id, "map": stage.map, "observed_event": event, "action": action, "original_targets": targets, **details}
    STEPS.append(row)


def inventory(name, item, observed_event, **details):
    if observed_event not in parse_tsc((DATA / "ArmsItem.tsc").read_bytes()):
        raise ValueError("Undefined original inventory observation")
    STEPS.append({"name": name, "action": "inventory_select_and_use", "item": item, "observed_page": "ArmsItem", "observed_event": observed_event, **details})


