def select_ending(route, ending):
    selected = []
    for row in route["steps"]:
        if ending in row.get("for_endings", ["bad", "normal", "best"]):
            selected.append(row)
        if ending == "bad" and row.get("terminal"):
            break
    return {**route, "selected_ending": ending, "steps": selected}


if __name__ == "__main__":
    path = Path(__file__).with_name("main_story_route.json")
    route = build()
    path.write_text(json.dumps(route, indent=2) + "\n")
    print(f"Wrote {len(route['steps'])} source-checked route steps to {path}")
    for ending in ("bad", "normal", "best"):
        selected = select_ending(route, ending)
        output = path.with_name(f"{ending}_route.json")
        output.write_text(json.dumps(selected, indent=2) + "\n")
        print(f"Wrote {len(selected['steps'])} {ending} route steps to {output}")
